[
  {"kind": "narration", "speaker_id": null, "text": "At the farm vegetable garden, rows of dark soil lie under a deepening dusk, the first crickets tuning up as Wren and Ash stand at the edge of the tilled beds.", "cited_fact_keys": ["place", "spots", "previously"]},
  {"kind": "narration", "speaker_id": null, "text": "Wren turns from the garden, wiping a hand on their tunic, and tries again to raise the topic that has hung between them since nightfall — the rocky islets south of Corvane.", "cited_fact_keys": ["attempt:communicate"]},
  {"kind": "narration", "speaker_id": null, "text": "Ash holds still, listening, the weight of the day settling in their shoulders as they let Wren's words go on.", "cited_fact_keys": ["attempt:wait", "reaction:1"]}
]

