  {"kind": "narration", "speaker_id": null, "text": "At the Hearth, the hearth fire pops and the smell of woodsmoke hangs in the air as Wren leans in, gesturing toward the dark beyond the window and trying to tell Ash about the rocky islets south of Corvane.", "cited_fact_keys": ["places", "attempt:communicate", "previously"]},
  {"kind": "narration", "speaker_id": null, "text": "Ash watches Wren's hands and half-formed words, leaning closer over the table as they try to ask back about those same rocky islets.", "cited_fact_keys": ["attempt:communicate", "previously"]},
  {"kind": "narration", "speaker_id": null, "text": "Wren, seeing Ash's intent listening, speaks about the rocky islets south of Corvane, the words spilling out with a question in their tone.", "cited_fact_keys": ["reaction:1", "attempt:communicate"]},
  {"kind": "narration", "speaker_id": null, "text": "Ash responds, turning the talk back to those islets, pressing for what Wren knows, their eyes steady in the firelight.", "cited_fact_keys": ["reaction:2", "attempt:communicate"]}
]

